#!/usr/bin/env node
import { writeFile } from "node:fs/promises";
import { buildJwwBytes } from "../src/jww/writer.js";
import { parseJwwDocumentHeader } from "../src/jww/documentHeader.js";

// Generated inventory is reproducible evidence of implementation coverage,
// not an independent oracle for either Jw_cad interpretation or its runtime.
const header = parseJwwDocumentHeader(buildJwwBytes({ entities: [], version: 700 }));
const lines = [
  "# JWW Header Field Matrix", "",
  "Reference: https://www.jwcad.net/jwdatafmt.txt (Version 7.02, internal v600/v700).", "",
  "Generated by `node tools/jww-format-field-matrix.mjs`. Companion: [gap audit](JWW_FORMAT_GAPS_AUDIT.md).",
  "Offsets refer only to the built-in template with its original CString lengths; they are not universal offsets.",
  "All rows are parsed into `meta.jwwInternalSettings.document.fields` and serialized with source-byte retention for unchanged values.",
  "`formatAudit.test.js` covers every descriptor's primitive round trip. This does not establish native application semantics for every value.",
  "`dummyBeforeSunpou` and `dummyAfterSunpou` are Gateway names for the unnamed serialized dummy fields.", "",
  `Fields: ${header.fields.length}; template header bytes: ${header.byteLength}.`, "",
  "| # | Official field / Gateway dummy name | Primitive | Template byte offset | Bytes | Status |",
  "| ---: | --- | --- | ---: | ---: | --- |",
];
header.fields.forEach((field, index) => lines.push(`| ${index + 1} | \`${field.name}\` | ${field.type} | ${field.offset} | ${field.byteLength} | Parsed / retained / ${index === 0 ? "writer version option" : "primitive write"} |`));
await writeFile(new URL("../docs/JWW_FORMAT_FIELD_MATRIX.md", import.meta.url), `${lines.join("\n")}\n`);
console.log(`Generated ${header.fields.length} field rows`);
